resource "azurerm_dashboard_grafana" "pipeline" {
  name                = "grafana-orders-pipeline"
  resource_group_name = azurerm_resource_group.pipeline.name
  location            = azurerm_resource_group.pipeline.location
  identity { type = "SystemAssigned" }
}

# Workspace's own Managed Identity needs Monitoring Reader -- separate from user login
resource "azurerm_role_assignment" "grafana_monitor_reader" {
  scope                = azurerm_resource_group.pipeline.id
  role_definition_name = "Monitoring Reader"
  principal_id         = azurerm_dashboard_grafana.pipeline.identity[0].principal_id
}

resource "azurerm_role_assignment" "grafana_admin_access" {
  scope                = azurerm_dashboard_grafana.pipeline.id
  role_definition_name = "Grafana Admin"
  principal_id         = data.azuread_group.data_platform_team.object_id
}
